<?php
namespace Tests\Feature;
use App\Models\{User,Task};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;
class TaskWorkflowTest extends TestCase {
 use RefreshDatabase;
 public function test_new_task_form_has_empty_contribution_and_difficulty_inputs():void{$u=User::factory()->create();$u->courses()->create(['name'=>'Basis Data']);$this->actingAs($u)->get('/tasks/create')->assertOk()->assertSee('name="grade_contribution"',false)->assertSee('placeholder="Masukkan persentase"',false)->assertSee('value=""',false)->assertSee('Pilih tingkat kesulitan');}
 public function test_priority_settings_are_locked_for_authenticated_users():void{$u=User::factory()->create();$this->actingAs($u)->put('/settings/priority',['urgency_weight'=>.2,'contribution_weight'=>.3,'difficulty_weight'=>.5,'horizon_days'=>14])->assertNotFound();$this->assertDatabaseMissing('priority_settings',['user_id'=>$u->id]);$this->actingAs($u)->get('/dashboard')->assertOk()->assertDontSee('Pengaturan Prioritas')->assertDontSee('Simpan bobot');}
 public function test_authenticated_user_can_create_and_complete_course_task_and_cannot_access_other_users_task():void{$a=User::factory()->create();$b=User::factory()->create();$course=$a->courses()->create(['name'=>'Basis Data','code'=>'SI101']);$foreignCourse=$b->courses()->create(['name'=>'Rahasia']);$task=$a->tasks()->create(['course_id'=>$course->id,'title'=>'Tugas Uji','grade_contribution'=>30,'difficulty'=>'Sulit','status'=>'Belum dikerjakan','deadline'=>now()->addDay(),'auto_score'=>.9643,'auto_priority'=>'Tinggi']);$this->actingAs($a)->get('/dashboard')->assertOk()->assertSee('Tugas Uji');$this->actingAs($b)->get('/tasks/'.$task->id.'/edit')->assertNotFound();$this->actingAs($a)->patch('/tasks/'.$task->id.'/status',['status'=>'Selesai'])->assertRedirect();$this->assertDatabaseHas('tasks',['id'=>$task->id,'status'=>'Selesai']);$this->actingAs($a)->delete('/courses/'.$course->id)->assertRedirect();$this->assertDatabaseMissing('courses',['id'=>$course->id]);$this->assertDatabaseMissing('tasks',['id'=>$task->id]);$this->assertDatabaseHas('courses',['id'=>$foreignCourse->id]);}
 public function test_task_creation_rejects_course_owned_by_another_user():void{$a=User::factory()->create();$b=User::factory()->create();$foreign=$b->courses()->create(['name'=>'Private']);$a->courses()->create(['name'=>'Own course']);$this->actingAs($a)->post('/tasks',['title'=>'Intrude','course_id'=>$foreign->id,'grade_contribution'=>20,'difficulty'=>'Sedang','status'=>'Belum dikerjakan'])->assertNotFound();$this->assertDatabaseCount('tasks',0);}
 public function test_task_store_calculates_and_saves_recommendation():void{$u=User::factory()->create();$course=$u->courses()->create(['name'=>'Pemrograman Web']);$this->actingAs($u)->get('/dashboard')->assertOk();$this->actingAs($u)->post('/tasks',['title'=>'Proyek dekat deadline','course_id'=>$course->id,'deadline'=>now()->addDay()->format('Y-m-d H:i:s'),'grade_contribution'=>30,'difficulty'=>'Sulit','status'=>'Belum dikerjakan'])->assertRedirect('/tasks');$this->actingAs($u)->get('/tasks')->assertOk()->assertSee('Proyek dekat deadline');$this->assertDatabaseHas('tasks',['title'=>'Proyek dekat deadline','auto_score'=>0.9643,'auto_priority'=>'Tinggi']);}
 public function test_empty_courses_redirect_task_creation_to_course_management():void{$u=User::factory()->create();$this->actingAs($u)->get('/tasks/create')->assertRedirect(route('courses.index'));$this->actingAs($u)->get('/courses')->assertOk()->assertSee('Belum ada mata kuliah')->assertSee('Tambah mata kuliah pertama');$this->actingAs($u)->post('/tasks',[])->assertRedirect(route('courses.index'));}
 public function test_course_management_has_own_route_and_crud():void{$u=User::factory()->create();$this->actingAs($u)->post('/courses',['name'=>'Basis Data','code'=>'IF101','lecturer'=>'Dosen A'])->assertRedirect();$course=$u->courses()->firstOrFail();$this->actingAs($u)->get('/courses')->assertOk()->assertSee('Basis Data');$this->actingAs($u)->put('/courses/'.$course->id,['name'=>'Basis Data Lanjut','code'=>'IF102','lecturer'=>'Dosen B'])->assertRedirect();$this->assertDatabaseHas('courses',['id'=>$course->id,'name'=>'Basis Data Lanjut']);}
}
